package com.example.demo;

import org.springframework.boot.context.properties.ConfigurationProperties;

@ConfigurationProperties(prefix = "greeting")
public record GreetingSettings(String prefix, int maxLength) {}

package com.example.demo;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableConfigurationProperties(GreetingSettings.class)
public class GreetingConfiguration {}

package com.example.demo;

import org.springframework.stereotype.Component;

@Component
public class GreetingPolicy {
    private final GreetingSettings settings;

    public GreetingPolicy(GreetingSettings settings) {
        this.settings = settings;
    }

    public boolean accepts(String name) {
        return name.length() <= settings.maxLength();
    }
}

